import type { Metadata } from "next";
import { site } from "./site";

/** The site-wide share image generated by app/opengraph-image.tsx. */
const shareImage = { url: "/opengraph-image", width: 1200, height: 630, alt: `${site.name} — ${site.tagline}` };

/** Per-page metadata with canonical URL and matching Open Graph / Twitter tags. */
export function pageMetadata({
  title,
  description,
  path,
}: {
  title: string;
  description: string;
  path: string;
}): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    // Page-level openGraph replaces the inherited one, so the share image is set again here.
    openGraph: { title: `${title} | ${site.name}`, description, url: path, siteName: site.name, type: "website", images: [shareImage] },
    twitter: { card: "summary_large_image", title: `${title} | ${site.name}`, description, images: [shareImage.url] },
  };
}
